18: export function stripSessionPrefix(fullPath: string): string {
19:   if (!fullPath) return "";
20: 
21:   // 1. .../sandboxes/{uuid}/sessions/{uuid}/REST  →  REST
22:   //    Matches local dev (always sandboxes + sessions)
23:   const sbSession = fullPath.match(
24:     /\/sandboxes\/[0-9a-f-]+\/sessions\/[0-9a-f-]+\/(.+)$/
25:   );
26:   if (sbSession?.[1]) return sbSession[1];
27: 
28:   // 2. .../sessions/{uuid}/REST  →  REST
29:   //    Matches kubernetes (e.g. /workspace/sessions/...)
30:   const session = fullPath.match(/\/sessions\/[0-9a-f-]+\/(.+)$/);
31:   if (session?.[1]) return session[1];
32: 
33:   // 3. Fallback: keep last 3 path segments for context
34:   //    /some/unknown/deep/path/to/file.tsx  →  path/to/file.tsx
35:   const segments = fullPath.split("/").filter(Boolean);
36:   if (segments.length > 3) return segments.slice(-3).join("/");

