20: function fakeInstall(root: string, name: string, version: string): string {
21:   const pkg = join(root, name);
22:   const distClaude = join(pkg, 'dist', 'claude');
23:   mkdirSync(distClaude, { recursive: true });
24:   writeFileSync(join(pkg, 'package.json'), JSON.stringify({ name: '@nanonets/graft', version }));
25:   // CJS on purpose: no "type" field, so `import()` hands back module.exports and
26:   // `m.main(...)` resolves — same shape the real dist has for the shim's call.
27:   writeFileSync(
28:     join(distClaude, 'hooks.js'),
29:     `module.exports.main = () => require('node:fs').writeFileSync(process.env.MARKER, ${JSON.stringify(version)});\n`,
30:   );
31:   return distClaude;
32: }

